using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using System.Xml.Linq;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;

namespace PaymentAuthorization.IntegrationTest.Architecture;

public sealed class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";

    // The language core only: no I/O, network, persistence, serialization or reflection.
    private static readonly string[] LanguageCore =
    [
        "System",
        "System.Collections.Generic",
        "System.Threading",
        "System.Threading.Tasks",
        "System.Runtime.CompilerServices",
        "System.Diagnostics.CodeAnalysis",
    ];

    [Fact]
    public void Domain_depends_only_on_Domain_and_the_language_core()
    {
        var violations = Violations(typeof(Money).Assembly, [DomainNs]);

        Assert.True(violations.Count == 0, "Violations: " + string.Join("; ", violations));
    }

    [Fact]
    public void Application_depends_only_on_Application_Domain_and_the_language_core()
    {
        var violations = Violations(typeof(AuthorizePayment).Assembly, [DomainNs, ApplicationNs]);

        Assert.True(violations.Count == 0, "Violations: " + string.Join("; ", violations));
    }

    [Theory]
    [InlineData("Domain", new string[0])]
    [InlineData("Application", new[] { "Domain" })]
    [InlineData("Infrastructure", new[] { "Application" })]
    public void Each_project_references_only_its_inner_neighbour(string layer, string[] allowed)
    {
        var csproj = Path.Combine(SolutionRoot(), "src", $"PaymentAuthorization.{layer}", $"PaymentAuthorization.{layer}.csproj");
        var doc = XDocument.Load(csproj);

        var projects = doc.Descendants("ProjectReference")
            .Select(e => Path.GetFileNameWithoutExtension((string)e.Attribute("Include")!))
            .ToList();
        var packages = doc.Descendants("PackageReference").Select(e => (string)e.Attribute("Include")!).ToList();
        var expected = allowed.Select(a => $"PaymentAuthorization.{a}").ToList();

        Assert.Equal(expected.Order(), projects.Order());
        if (layer != "Infrastructure") Assert.Empty(packages);
    }

    private static List<string> Violations(Assembly assembly, string[] ownNamespaces)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var reader = pe.GetMetadataReader();
        var ownName = assembly.GetName().Name;
        var violations = new SortedSet<string>();

        foreach (var handle in reader.TypeReferences)
        {
            var reference = reader.GetTypeReference(handle);
            var ns = reader.GetString(reference.Namespace);
            var name = reader.GetString(reference.Name);
            var scope = reference.ResolutionScope;
            var scopeAssembly = scope.Kind == HandleKind.AssemblyReference
                ? reader.GetString(reader.GetAssemblyReference((AssemblyReferenceHandle)scope).Name)
                : null;

            if (scope.Kind == HandleKind.TypeReference)
            {
                continue; // nested type: judged through its enclosing type
            }

            var allowed = ownNamespaces.Any(o => ns == o || ns.StartsWith(o + ".", StringComparison.Ordinal))
                || LanguageCore.Contains(ns);
            if (!allowed) violations.Add($"{assembly.GetName().Name} -> {ns}.{name} ({scopeAssembly ?? ownName})");
        }

        return [.. violations];
    }

    private static string SolutionRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "PaymentAuthorization.slnx"))) dir = dir.Parent;
        return dir?.FullName ?? throw new InvalidOperationException("Solution root not found.");
    }
}
